-- Independent, transactional migration executed only by run-db-migrations.sh after backup.
CREATE TABLE kitchen_categories (
id TEXT PRIMARY KEY, name TEXT NOT NULL, icon TEXT NOT NULL, position INTEGER NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE kitchen_recipes (
id UUID PRIMARY KEY, category_id TEXT NOT NULL REFERENCES kitchen_categories(id),
version INTEGER NOT NULL CHECK(version>0), published BOOLEAN NOT NULL DEFAULT FALSE,
body JSONB NOT NULL CHECK(jsonb_typeof(body)='object'), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX kitchen_recipes_category ON kitchen_recipes(category_id) WHERE published;
