INSERT INTO kitchen_recipes(id,category_id,version,published,body) VALUES ('937fdec9-f486-58e7-b845-11d63770f1c6','congee',1,true,'{"recipeId": "937fdec9-f486-58e7-b845-11d63770f1c6", "name": "南瓜小米粥", "category": "congee", "description": "两人份的家常南瓜小米粥，用常见食材完成。", "servings": 2, "duration": 40, "difficulty": "简单", "ingredients": [{"name": "小米", "quantity": 80, "unit": "克"}, {"name": "南瓜", "quantity": 200, "unit": "克"}, {"name": "水", "quantity": 1000, "unit": "毫升"}], "preparation": ["南瓜洗净去皮，切成1厘米小块；米类淘洗，燕麦片按包装准备。"], "steps": [{"number": 1, "action": "煮开", "ingredients": ["小米", "南瓜", "水"], "utensils": ["汤锅", "长柄勺"], "instruction": "水烧开，放入谷物和蔬菜，搅拌后转小火。", "illustrationUrl": null}, {"number": 2, "action": "慢煮", "ingredients": ["粥"], "utensils": ["汤锅", "长柄勺"], "instruction": "锅盖留缝，小火煮25至35分钟，期间搅拌并留意防溢。燕麦片若包装要求更短时间，先煮软蔬菜再按包装时间加入。", "illustrationUrl": null}, {"number": 3, "action": "检查熟度", "ingredients": ["粥"], "utensils": ["勺子"], "instruction": "确认谷物无硬芯、蔬菜可轻松压碎；过稠时加少量开水再煮沸。", "illustrationUrl": null}, {"number": 4, "action": "盛出", "ingredients": ["粥"], "utensils": ["碗"], "instruction": "关火后盛出，放至适口温度再吃，小心烫伤。", "illustrationUrl": null}], "notes": ["煮粥期间有人看管，避免溢锅和干烧。", "处理食材前后洗手；生熟食材和器具分开。", "有过敏史时先核对食材。用量为两人份参考，实际火力和锅具会影响时间。"], "coverImage": null, "illustrationStatus": "unavailable", "recipeVersion": 1, "source": "Linko Moment 原创文字试行菜谱 v1；规则校验，尚待人工烹饪复核。", "mealPreferences": ["breakfast", "dinner"]}'::jsonb);
INSERT INTO kitchen_recipes(id,category_id,version,published,body) VALUES ('a2889d17-bdd6-5904-88c7-040ff866a566','congee',1,true,'{"recipeId": "a2889d17-bdd6-5904-88c7-040ff866a566", "name": "红薯大米粥", "category": "congee", "description": "两人份的家常红薯大米粥，用常见食材完成。", "servings": 2, "duration": 40, "difficulty": "简单", "ingredients": [{"name": "大米", "quantity": 80, "unit": "克"}, {"name": "红薯", "quantity": 200, "unit": "克"}, {"name": "水", "quantity": 1000, "unit": "毫升"}], "preparation": ["红薯洗净去皮，切成1厘米小块；米类淘洗，燕麦片按包装准备。"], "steps": [{"number": 1, "action": "煮开", "ingredients": ["大米", "红薯", "水"], "utensils": ["汤锅", "长柄勺"], "instruction": "水烧开，放入谷物和蔬菜，搅拌后转小火。", "illustrationUrl": null}, {"number": 2, "action": "慢煮", "ingredients": ["粥"], "utensils": ["汤锅", "长柄勺"], "instruction": "锅盖留缝，小火煮25至35分钟，期间搅拌并留意防溢。燕麦片若包装要求更短时间，先煮软蔬菜再按包装时间加入。", "illustrationUrl": null}, {"number": 3, "action": "检查熟度", "ingredients": ["粥"], "utensils": ["勺子"], "instruction": "确认谷物无硬芯、蔬菜可轻松压碎；过稠时加少量开水再煮沸。", "illustrationUrl": null}, {"number": 4, "action": "盛出", "ingredients": ["粥"], "utensils": ["碗"], "instruction": "关火后盛出，放至适口温度再吃，小心烫伤。", "illustrationUrl": null}], "notes": ["煮粥期间有人看管，避免溢锅和干烧。", "处理食材前后洗手；生熟食材和器具分开。", "有过敏史时先核对食材。用量为两人份参考，实际火力和锅具会影响时间。"], "coverImage": null, "illustrationStatus": "unavailable", "recipeVersion": 1, "source": "Linko Moment 原创文字试行菜谱 v1；规则校验，尚待人工烹饪复核。", "mealPreferences": ["breakfast", "dinner"]}'::jsonb);
